#include <stdio.h>

int main(void) {
    int n, edge = 0, far = 0, jumps = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (i > far) {
            puts("-1");
            return 0;
        }
        if (i + x > far)
            far = i + x;
        if (i == edge && i < n - 1) {
            edge = far;
            jumps++;
        }
    }
    printf("%d\n", jumps);
    return 0;
}

