#include <stdio.h>

int main(void) {

    int n,m,a[200][200],best=0;
    scanf("%d%d",&n,&m);
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) scanf("%d",&a[i][j]);
    for(int top=0;top<n;top++){
        int blocked[200]={0};
        for(int bottom=top;bottom<n;bottom++){
            int run=0;
            for(int j=0;j<m;j++){
                blocked[j]|=!a[bottom][j];
                run=blocked[j]?0:run+1;
                int area=run*(bottom-top+1);
                if(area>best) best=area;
            }
        }
    }
    printf("%d\n",best);
    return 0;
}

